/**
 * guides/LEGACY-REMOVAL.md is the manifest of what 13.0.0 removes. SEMVER.md
 * lets a major release remove only what an earlier minor release marked
 * `@deprecated`, so every surface the manifest's table names must be marked
 * in the API report (`etc/esi.ts.api.md`, regenerated by `npm run
 * api-report`), which is what TypeDoc and an editor show a consumer.
 *
 * The cases fail when a name in the table is not in the report (a typo, or
 * an export that was renamed), when a named declaration or member lost its
 * tag, and when a domain client exists that the table does not list.
 */
import { readFileSync } from 'fs';
import * as path from 'path';

const ROOT = path.resolve(__dirname, '../../..');
const manifest = readFileSync(
  path.join(ROOT, 'guides/LEGACY-REMOVAL.md'),
  'utf8',
);
const report = readFileSync(path.join(ROOT, 'etc/esi.ts.api.md'), 'utf8');
const reportLines = report.split('\n');

interface Surface {
  readonly name: string;
  readonly since: string;
  readonly removedIn: string;
}

/** The rows of the table under `## Surfaces`, up to the next heading. */
function surfaces(markdown: string): Surface[] {
  const start = markdown.indexOf('\n## Surfaces\n');
  if (start < 0) return [];
  const rest = markdown.slice(start + 1);
  const end = rest.indexOf('\n## ', 1);
  const section = end < 0 ? rest : rest.slice(0, end);
  const rows: Surface[] = [];
  for (const line of section.split('\n')) {
    const cells = line.split('|').map((c) => c.trim());
    // A row reads `| `Name` | kind | since | replacement | removed |`.
    const name = /^`([A-Za-z]\w*(?:\.\w+)?)`$/.exec(cells[1] ?? '');
    if (!name) continue;
    rows.push({
      name: name[1]!,
      since: cells[3] ?? '',
      removedIn: cells[cells.length - 2] ?? '',
    });
  }
  return rows;
}

const DECLARATION =
  /^export (?:declare )?(?:abstract )?(?:class|interface|type|function|const|enum) (\w+)\b/;

/** The index of `name`'s top-level declaration in the report, or -1. */
function declarationIndex(name: string): number {
  return reportLines.findIndex((line) => DECLARATION.exec(line)?.[1] === name);
}

/** The comment lines directly above line `index`. */
function commentAbove(index: number): string[] {
  const comments: string[] = [];
  for (let i = index - 1; i >= 0; i--) {
    const line = reportLines[i]!.trim();
    if (!line.startsWith('//')) break;
    comments.push(line);
  }
  return comments;
}

/** The index of member `member` inside the class declared at `classIndex`, or -1. */
function memberIndex(classIndex: number, member: string): number {
  const pattern = new RegExp(
    `^\\s+(?:static |protected |abstract )*${member}[(<]`,
  );
  for (let i = classIndex + 1; i < reportLines.length; i++) {
    const line = reportLines[i]!;
    if (line === '}') return -1;
    if (pattern.test(line)) return i;
  }
  return -1;
}

function isDeprecated(name: string): 'missing' | 'untagged' | 'tagged' {
  const [owner, member] = name.split('.') as [string, string | undefined];
  const ownerIndex = declarationIndex(owner);
  if (ownerIndex < 0) return 'missing';
  const index = member ? memberIndex(ownerIndex, member) : ownerIndex;
  if (index < 0) return 'missing';
  return commentAbove(index).some((c) => c.includes('@deprecated'))
    ? 'tagged'
    : 'untagged';
}

const rows = surfaces(manifest);

describe('guides/LEGACY-REMOVAL.md and the API report agree', () => {
  it('reads the surfaces table', () => {
    // An empty table would make every case below vacuous.
    expect(rows.length).toBeGreaterThanOrEqual(50);
    expect(rows.map((r) => r.name)).toEqual(
      expect.arrayContaining([
        'EsiClient',
        'EsiClientBuilder',
        'EsiApiFactory',
        'EsiApiFactory.createClient',
        'ApiClientBuilder',
        'BaseEsiClient',
        'EsiTokenManager.createClient',
      ]),
    );
  });

  it('names each surface once', () => {
    const names = rows.map((r) => r.name);
    expect(names.filter((n, i) => names.indexOf(n) !== i)).toEqual([]);
  });

  it('marks every surface in the table @deprecated in etc/esi.ts.api.md', () => {
    const problems = rows
      .map((r) => ({ name: r.name, state: isDeprecated(r.name) }))
      .filter((r) => r.state !== 'tagged');
    expect(problems).toEqual([]);
  });

  it('gives every surface a deprecation release and 13.0.0 as its removal', () => {
    for (const row of rows) {
      expect({ name: row.name, since: row.since }).toEqual({
        name: row.name,
        since: expect.stringMatching(/^\d+\.\d+\.0$/),
      });
      expect({ name: row.name, removedIn: row.removedIn }).toEqual({
        name: row.name,
        removedIn: '13.0.0',
      });
    }
  });

  it('lists every domain client the report exports', () => {
    const clients = reportLines
      .map((line) => /^export class (\w+) extends BaseEsiClient\b/.exec(line))
      .filter((m): m is RegExpExecArray => m !== null)
      .map((m) => m[1]!);
    expect(clients).toHaveLength(39);
    const listed = new Set(rows.map((r) => r.name));
    expect(clients.filter((c) => !listed.has(c))).toEqual([]);
  });

  it('reports a name that is not in the API report as missing', () => {
    // Guards the lookup itself: a typo in the table must not read as tagged.
    expect(isDeprecated('NoSuchExport')).toBe('missing');
    expect(isDeprecated('EsiClient.noSuchMember')).toBe('missing');
  });

  it('reports a declaration without the tag as untagged', () => {
    // createEsi's runtime and the error classes stay; the check must tell.
    expect(isDeprecated('EsiError')).toBe('untagged');
    expect(isDeprecated('EsiTokenManager.identity')).toBe('untagged');
  });
});
